UPDATE facodi.project_profiles SET translations=jsonb_set(jsonb_set(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"description":"Marcelo started FACODI to connect scattered videos, documentation and public educational resources into meaningful study paths. Born from his own experience as a student, the project combines software engineering with open, community-led learning."}'::jsonb,true),'{es}',coalesce(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"description":"Marcelo started FACODI to connect scattered videos, documentation and public educational resources into meaningful study paths. Born from his own experience as a student, the project combines software engineering with open, community-led learning."}'::jsonb,true)->'es','{}'::jsonb)||'{"description":"Marcelo creó FACODI para conectar vídeos, documentación y recursos educativos que encontraba dispersos. A partir de su experiencia como estudiante, el proyecto une ingeniería de software y aprendizaje abierto en comunidad."}'::jsonb,true),'{fr}',coalesce(jsonb_set(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"description":"Marcelo started FACODI to connect scattered videos, documentation and public educational resources into meaningful study paths. Born from his own experience as a student, the project combines software engineering with open, community-led learning."}'::jsonb,true),'{es}',coalesce(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"description":"Marcelo started FACODI to connect scattered videos, documentation and public educational resources into meaningful study paths. Born from his own experience as a student, the project combines software engineering with open, community-led learning."}'::jsonb,true)->'es','{}'::jsonb)||'{"description":"Marcelo creó FACODI para conectar vídeos, documentación y recursos educativos que encontraba dispersos. A partir de su experiencia como estudiante, el proyecto une ingeniería de software y aprendizaje abierto en comunidad."}'::jsonb,true)->'fr','{}'::jsonb)||'{"description":"Marcelo a lancé FACODI pour relier vidéos, documentation et ressources pédagogiques publiques en parcours cohérents. Né de sa propre expérience d''étudiant, ce projet associe génie logiciel et apprentissage ouvert."}'::jsonb,true),updated_at=now() WHERE slug='marcelo-santos';
UPDATE facodi.project_profiles SET translations=jsonb_set(jsonb_set(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"headline":"Academic context, not a degree issued by FACODI.","description":"FACODI is connected to the University of Algarve through the SEA-EU context. Public study plans help organise units and resources, but FACODI does not award ECTS, accreditation or academic equivalence."}'::jsonb,true),'{es}',coalesce(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"headline":"Academic context, not a degree issued by FACODI.","description":"FACODI is connected to the University of Algarve through the SEA-EU context. Public study plans help organise units and resources, but FACODI does not award ECTS, accreditation or academic equivalence."}'::jsonb,true)->'es','{}'::jsonb)||'{"headline":"Referencia académica, no un título de FACODI.","description":"FACODI está vinculado al contexto de la Universidad del Algarve y SEA-EU. Los planes de estudio públicos sirven para organizar contenidos, pero FACODI no otorga créditos ECTS ni equivalencias académicas."}'::jsonb,true),'{fr}',coalesce(jsonb_set(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"headline":"Academic context, not a degree issued by FACODI.","description":"FACODI is connected to the University of Algarve through the SEA-EU context. Public study plans help organise units and resources, but FACODI does not award ECTS, accreditation or academic equivalence."}'::jsonb,true),'{es}',coalesce(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"headline":"Academic context, not a degree issued by FACODI.","description":"FACODI is connected to the University of Algarve through the SEA-EU context. Public study plans help organise units and resources, but FACODI does not award ECTS, accreditation or academic equivalence."}'::jsonb,true)->'es','{}'::jsonb)||'{"headline":"Referencia académica, no un título de FACODI.","description":"FACODI está vinculado al contexto de la Universidad del Algarve y SEA-EU. Los planes de estudio públicos sirven para organizar contenidos, pero FACODI no otorga créditos ECTS ni equivalencias académicas."}'::jsonb,true)->'fr','{}'::jsonb)||'{"headline":"Un repère académique, pas un diplôme FACODI.","description":"FACODI s''inscrit dans le contexte de l''Université de l''Algarve et de SEA-EU. Les plans d''études publics structurent les ressources; FACODI ne délivre ni crédits ECTS ni équivalences universitaires."}'::jsonb,true),updated_at=now() WHERE slug='ualg';
UPDATE facodi.project_profiles SET translations=jsonb_set(jsonb_set(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"headline":"Student ideas that cross borders.","description":"FACODI was selected for SEA-EU Student-Led Projects 2026 and presented at the third Being SEA-EU Conference in Gdańsk. The programme provides a European context; it does not mean every alliance university endorses each FACODI resource."}'::jsonb,true),'{es}',coalesce(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"headline":"Student ideas that cross borders.","description":"FACODI was selected for SEA-EU Student-Led Projects 2026 and presented at the third Being SEA-EU Conference in Gdańsk. The programme provides a European context; it does not mean every alliance university endorses each FACODI resource."}'::jsonb,true)->'es','{}'::jsonb)||'{"headline":"Ideas de estudiantes que cruzan fronteras.","description":"FACODI fue seleccionado en SEA-EU Student-Led Projects 2026 y presentado en Being SEA-EU en Gdańsk. El programa aporta un contexto europeo, pero no implica la aprobación de todos los materiales por cada universidad."}'::jsonb,true),'{fr}',coalesce(jsonb_set(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"headline":"Student ideas that cross borders.","description":"FACODI was selected for SEA-EU Student-Led Projects 2026 and presented at the third Being SEA-EU Conference in Gdańsk. The programme provides a European context; it does not mean every alliance university endorses each FACODI resource."}'::jsonb,true),'{es}',coalesce(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"headline":"Student ideas that cross borders.","description":"FACODI was selected for SEA-EU Student-Led Projects 2026 and presented at the third Being SEA-EU Conference in Gdańsk. The programme provides a European context; it does not mean every alliance university endorses each FACODI resource."}'::jsonb,true)->'es','{}'::jsonb)||'{"headline":"Ideas de estudiantes que cruzan fronteras.","description":"FACODI fue seleccionado en SEA-EU Student-Led Projects 2026 y presentado en Being SEA-EU en Gdańsk. El programa aporta un contexto europeo, pero no implica la aprobación de todos los materiales por cada universidad."}'::jsonb,true)->'fr','{}'::jsonb)||'{"headline":"Des idées d''étudiants au-delà des frontières.","description":"FACODI a été sélectionné dans SEA-EU Student-Led Projects 2026 et présenté à Being SEA-EU à Gdańsk. Ce cadre européen ne signifie pas que chaque université approuve les ressources FACODI."}'::jsonb,true),updated_at=now() WHERE slug='sea-eu';
UPDATE facodi.project_profiles SET translations=jsonb_set(jsonb_set(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"headline":"Software engineering for open learning.","description":"Corvanis is publicly presented as a FACODI technology and development partner. Its collaboration supports software engineering and platform evolution, while FACODI retains its own educational mission and editorial curation."}'::jsonb,true),'{es}',coalesce(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"headline":"Software engineering for open learning.","description":"Corvanis is publicly presented as a FACODI technology and development partner. Its collaboration supports software engineering and platform evolution, while FACODI retains its own educational mission and editorial curation."}'::jsonb,true)->'es','{}'::jsonb)||'{"headline":"Ingeniería de software para aprender en abierto.","description":"Corvanis figura públicamente como socio tecnológico de FACODI. La colaboración apoya el desarrollo de la plataforma, mientras FACODI mantiene su misión educativa y sus decisiones editoriales."}'::jsonb,true),'{fr}',coalesce(jsonb_set(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"headline":"Software engineering for open learning.","description":"Corvanis is publicly presented as a FACODI technology and development partner. Its collaboration supports software engineering and platform evolution, while FACODI retains its own educational mission and editorial curation."}'::jsonb,true),'{es}',coalesce(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"headline":"Software engineering for open learning.","description":"Corvanis is publicly presented as a FACODI technology and development partner. Its collaboration supports software engineering and platform evolution, while FACODI retains its own educational mission and editorial curation."}'::jsonb,true)->'es','{}'::jsonb)||'{"headline":"Ingeniería de software para aprender en abierto.","description":"Corvanis figura públicamente como socio tecnológico de FACODI. La colaboración apoya el desarrollo de la plataforma, mientras FACODI mantiene su misión educativa y sus decisiones editoriales."}'::jsonb,true)->'fr','{}'::jsonb)||'{"headline":"Du génie logiciel pour l''apprentissage ouvert.","description":"Corvanis est présenté publiquement comme partenaire technique de FACODI. Cette collaboration soutient le développement de la plateforme, sans remplacer sa mission éducative ou ses choix éditoriaux."}'::jsonb,true),updated_at=now() WHERE slug='corvanis';
UPDATE facodi.project_profiles SET translations=jsonb_set(jsonb_set(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"headline":"The code has a home. Knowledge is for everyone.","description":"The Open2Tech/facodi repository hosts the application''s source code and technical collaboration. This identifies the development space, not a legal owner or financial sponsor of the educational initiative."}'::jsonb,true),'{es}',coalesce(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"headline":"The code has a home. Knowledge is for everyone.","description":"The Open2Tech/facodi repository hosts the application''s source code and technical collaboration. This identifies the development space, not a legal owner or financial sponsor of the educational initiative."}'::jsonb,true)->'es','{}'::jsonb)||'{"headline":"El código tiene casa. El conocimiento es de todos.","description":"El repositorio Open2Tech/facodi reúne el código y la colaboración técnica. Este vínculo no acredita propiedad legal ni patrocinio económico de la iniciativa educativa."}'::jsonb,true),'{fr}',coalesce(jsonb_set(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"headline":"The code has a home. Knowledge is for everyone.","description":"The Open2Tech/facodi repository hosts the application''s source code and technical collaboration. This identifies the development space, not a legal owner or financial sponsor of the educational initiative."}'::jsonb,true),'{es}',coalesce(jsonb_set(translations,'{en}',coalesce(translations->'en','{}'::jsonb)||'{"headline":"The code has a home. Knowledge is for everyone.","description":"The Open2Tech/facodi repository hosts the application''s source code and technical collaboration. This identifies the development space, not a legal owner or financial sponsor of the educational initiative."}'::jsonb,true)->'es','{}'::jsonb)||'{"headline":"El código tiene casa. El conocimiento es de todos.","descriptio